create table if not exists public.phase2_lineup_hourly_metrics (bucket timestamptz primary key,total_matches integer not null,missing integer not null,partial integer not null,predicted_full integer not null,confirmed integer not null,coverage_pct numeric not null,created_at timestamptz not null default now());
create or replace function public.snapshot_phase2_lineup_coverage() returns void language sql security definer set search_path=public as $$ insert into phase2_lineup_hourly_metrics(bucket,total_matches,missing,partial,predicted_full,confirmed,coverage_pct) select date_trunc('hour',now()),count(*),count(*) filter(where lineup_status='MISSING'),count(*) filter(where lineup_status='PARTIAL'),count(*) filter(where lineup_status='PREDICTED_FULL'),count(*) filter(where lineup_status='CONFIRMED'),round(100.0*count(*) filter(where lineup_status in ('PREDICTED_FULL','CONFIRMED'))/nullif(count(*),0),1) from phase2_lineup_coverage_current on conflict(bucket) do update set total_matches=excluded.total_matches,missing=excluded.missing,partial=excluded.partial,predicted_full=excluded.predicted_full,confirmed=excluded.confirmed,coverage_pct=excluded.coverage_pct,created_at=now(); $$;
select cron.schedule('phase2-lineup-hourly-metrics','55 * * * *',$$select public.snapshot_phase2_lineup_coverage();$$);
